import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    a = [int(x) for x in data[1:]]

    if n == 0:
        print(0)
        return

    # dp[i] stores the length of the longest alternating subsequence ending at index i
    dp = [1] * n
    max_len = 1

    for i in range(n):
        for j in range(i):
            # Condition 1: Absolute value must be strictly increasing
            # Condition 2: Signs must be opposite (product < 0)
            if abs(a[i]) > abs(a[j]) and a[i] * a[j] < 0:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
        if dp[i] > max_len:
            max_len = dp[i]

    print(max_len)

if __name__ == '__main__':
    solve()

