import sys

def solve():
    meme = sys.stdin.read().strip()
    if not meme:
        return

    lower_meme = meme.lower()

    def find_subsequence(target):
        # Returns the starting index of the earliest match of the subsequence 'target' in lower_meme, or infinity if not found.
        it_target = iter(target)
        first_char = next(it_target)
        try:
            start_pos = lower_meme.index(first_char)
        except ValueError:
            return float('inf')

        curr_pos = start_pos
        for char in it_target:
            try:
                curr_pos = lower_meme.index(char, curr_pos + 1)
            except ValueError:
                return float('inf')
        return start_pos

    # Keywords and their corresponding receivers
    matches = [
        (find_subsequence('bug'), "IT - 'Roma'"),
        (find_subsequence('boom'), "chemistry - 'Maxim'"),
        (find_subsequence('edits'), "design - 'Danik'")
    ]

    valid_matches = [m for m in matches if m[0] != float('inf')]

    if not valid_matches:
        print("other - 'Vlad'")
    else:
        # Choose the one with the earliest start position
        valid_matches.sort(key=lambda x: x[0])
        print(valid_matches[0][1])

if __name__ == '__main__':
    solve()

import sys

def countTwosAtDigitPosition(n, p):
    if n < p:
        return 0
    left = n // (p * 10)
    cur = (n // p) % 10
    right = n % p

    count = left * p
    if cur > 2:
        count += p
    elif cur == 2:
        count += right + 1
    return count

def countTwos(n):
    if n <= 0:
        return 0
    total_twos = 0
    p = 1
    while n // p > 0:
        total_twos += countTwosAtDigitPosition(n, p)
        p *= 10
    return total_twos

